import{addWebUiListener}from"chrome://resources/js/cr.js";import{getRequiredElement}from"chrome://resources/js/util_ts.js";import{DownloadInternalsBrowserProxyImpl,ServiceEntryState}from"./download_internals_browser_proxy.js";const browserProxy=DownloadInternalsBrowserProxyImpl.getInstance();const ongoingServiceEntries=[];const finishedServiceEntries=[];const serviceRequests=[];function removeGuidFromList(list,guid){const index=list.findIndex((entry=>entry.guid==guid));if(index!=-1){list.splice(index,1)}}function addOrUpdateEntryByGuid(list,newEntry){const index=list.findIndex((entry=>entry.guid==newEntry.guid));if(index!=-1){list[index]=newEntry}else{list.unshift(newEntry)}}function updateEntryTables(){const ongoingInput=new JsEvalContext({entries:ongoingServiceEntries});jstProcess(ongoingInput,getRequiredElement("download-service-ongoing-entries-info"));const finishedInput=new JsEvalContext({entries:finishedServiceEntries});jstProcess(finishedInput,getRequiredElement("download-service-finished-entries-info"))}function onServiceStatusChanged(state){getRequiredElement("service-state").textContent=state.serviceState;getRequiredElement("service-status-model").textContent=state.modelStatus;getRequiredElement("service-status-driver").textContent=state.driverStatus;getRequiredElement("service-status-file").textContent=state.fileMonitorStatus}function onServiceDownloadsAvailable(entries){for(let i=0;i<entries.length;i++){const entry=entries[i];if(entry.state==ServiceEntryState.COMPLETE){finishedServiceEntries.unshift(entry)}else{ongoingServiceEntries.unshift(entry)}}updateEntryTables()}function onServiceDownloadChanged(entry){if(entry.state==ServiceEntryState.COMPLETE){removeGuidFromList(ongoingServiceEntries,entry.guid);addOrUpdateEntryByGuid(finishedServiceEntries,entry)}else{addOrUpdateEntryByGuid(ongoingServiceEntries,entry)}updateEntryTables()}function onServiceDownloadFailed(entry){removeGuidFromList(ongoingServiceEntries,entry.guid);addOrUpdateEntryByGuid(finishedServiceEntries,entry);updateEntryTables()}function onServiceRequestMade(request){serviceRequests.unshift(request);const input=new JsEvalContext({requests:serviceRequests});jstProcess(input,getRequiredElement("download-service-request-info"))}function initialize(){addWebUiListener("service-status-changed",onServiceStatusChanged);addWebUiListener("service-downloads-available",onServiceDownloadsAvailable);addWebUiListener("service-download-changed",onServiceDownloadChanged);addWebUiListener("service-download-failed",onServiceDownloadFailed);addWebUiListener("service-request-made",onServiceRequestMade);getRequiredElement("start-download").onclick=function(){browserProxy.startDownload(getRequiredElement("download-url").value)};browserProxy.getServiceStatus().then(onServiceStatusChanged);browserProxy.getServiceDownloads().then(onServiceDownloadsAvailable)}document.addEventListener("DOMContentLoaded",initialize);